};

export const FACES = {
  happy: { name: 'Happy', glow: '#ffd36e', blurb: 'big sparkly smiles' },
  sleepy: { name: 'Sleepy', glow: '#ffc887', blurb: 'soft little yawns' },
  wink: { name: 'Wink', glow: '#ffdc8a', blurb: 'a cheeky little glow' },
  cat: { name: 'Kitty', glow: '#ffe6a8', blurb: 'purrfectly mysterious' },
  spooky: { name: 'Spooky', glow: '#a8ffd1', blurb: 'a classic green fright' },
};

export const ACCESSORIES = {
  none: { name: 'Bare', icon: '✦' },
  witch: { name: 'Witch Hat', icon: '🧙' },
  bow: { name: 'Big Bow', icon: '🎀' },
  crown: { name: 'Bloom Crown', icon: '👑' },
  ears: { name: 'Kitty Ears', icon: '🐱' },
  wings: { name: 'Bat Wings', icon: '🦇' },
};

export const RUSH_ACCESSORIES = ['witch', 'bow', 'crown', 'ears', 'wings'];

export const STAMPS = {
  star: { name: 'Star', icon: '⭐', color: '#ffe27a', glow: '#ffcf3d' },
  heart: { name: 'Heart', icon: '💗', color: '#ff9ec9', glow: '#ff5fa8' },
  moon: { name: 'Moon', icon: '🌙', color: '#cbb8ff', glow: '#9a7bff' },
  bat: { name: 'Bat', icon: '🦇', color: '#c3b2ff', glow: '#8c6dff' },
  flower: { name: 'Bloom', icon: '🌸', color: '#ffbcd6', glow: '#ff87b8' },
};

export const STAMP_LIMIT = 36;

export const SPIRITS = [
  { name: 'Mochi', color: '#d9f4ff', line: 'Something sleepy and soft, please…' },
  { name: 'Pip', color: '#ffe9bd', line: 'I want the spookiest little lantern!' },
  { name: 'Bun', color: '#ffd9ea', line: 'Make it fancy. Very, very fancy.' },
  { name: 'Nox', color: '#dcd4ff', line: 'A starry friend for my dark porch!' },
  { name: 'Tilly', color: '#d7ffe9', line: 'Surprise me — but make it cute!' },
];

export const COLOR_LINES = {
  ember: 'warm as a hearth',
  butter: 'sweet as candy corn',
  blush: 'soft as a petal',
  lilac: 'dreamy as dusk',
  mint: 'cool as moonmint',
  ash: 'mysterious as fog',
};

export const ALBUM_KEY = 'pumpkin-parlor-best';

export const TIER_LABEL = [
  { min: 5800, rank: 'S', title: 'Moonlight Royalty!', line: 'The spirits are absolutely dazzled. The patch will glow for a year.' },
  { min: 4400, rank: 'A', title: 'Patch favorite!', line: 'Five wishes granted with style. The little spirits are smitten.' },
  { min: 3000, rank: 'B', title: 'Lovely little lantern!', line: 'A few wishes wandered off, but the patch is still glowing.' },
  { min: 0, rank: 'C', title: 'The moon is patient.', line: 'The spirits had fun anyway. One more round? The patch believes in you.' },
];

import * as THREE from 'three';

// ---------- 2D shape builders (all lie in the XY plane, facing +Z) ----------

export function starShape(outer = 1, inner = 0.45, points = 5) {
  const s = new THREE.Shape();
  for (let i = 0; i < points * 2; i++) {
    const a = (i / (points * 2)) * Math.PI * 2 - Math.PI / 2;
    const r = i % 2 === 0 ? outer : inner;
    const x = Math.cos(a) * r;
    const y = Math.sin(a) * r;
    if (i === 0) s.moveTo(x, y);
    else s.lineTo(x, y);
  }
  s.closePath();
  return s;
}

export function heartShape() {
  const s = new THREE.Shape();
  s.moveTo(0, -0.86);
  s.bezierCurveTo(-0.12, -0.68, -0.98, -0.18, -0.86, 0.3);
  s.bezierCurveTo(-0.76, 0.78, -0.2, 0.86, 0, 0.42);
  s.bezierCurveTo(0.2, 0.86, 0.76, 0.78, 0.86, 0.3);
  s.bezierCurveTo(0.98, -0.18, 0.12, -0.68, 0, -0.86);
  s.closePath();
  return s;
}

export function moonShape() {
  const s = new THREE.Shape();
  s.moveTo(0.5, 0.98);
  s.bezierCurveTo(-0.72, 0.72, -0.72, -0.72, 0.5, -0.98);
  s.bezierCurveTo(-0.08, -0.42, -0.08, 0.42, 0.5, 0.98);
  s.closePath();
  return s;
}

export function ellipseShape(rx = 0.5, ry = 0.5) {
  const s = new THREE.Shape();
  s.absellipse(0, 0, rx, ry, 0, Math.PI * 2, false, 0);
  return s;
}

export function triangleShape(w = 0.5, h = 0.5) {
  const s = new THREE.Shape();
  s.moveTo(-w, -h * 0.72);
  s.lineTo(w, -h * 0.72);
  s.lineTo(0, h * 0.72);
  s.closePath();
  return s;
}

export function zigzagShape(w = 0.9, h = 0.24, teeth = 4) {
  const s = new THREE.Shape();
  s.moveTo(-w, h * 0.2);
  const step = (w * 2) / teeth;
  for (let i = 0; i < teeth; i++) {
    s.lineTo(-w + step * (i + 0.5), -h);
    s.lineTo(-w + step * (i + 1), h * 0.2);
  }
  s.lineTo(w, h);
  s.lineTo(-w, h);
  s.closePath();
  return s;
}

export function batWingShape(flip = false) {
  const s = new THREE.Shape();
  const f = flip ? -1 : 1;
  s.moveTo(0, 0.16);
  s.quadraticCurveTo(0.26 * f, 0.62, 0.66 * f, 0.44);
  s.quadraticCurveTo(0.48 * f, 0.2, 0.74 * f, 0.05);
  s.quadraticCurveTo(0.46 * f, 0.02, 0.52 * f, -0.26);
  s.quadraticCurveTo(0.24 * f, -0.12, 0.06 * f, -0.32);
  s.closePath();
  return s;
}

// ---------- glow material helper ----------

const matCache = new Map();
export function glowMaterial(color, intensity = 1.6) {
  const key = color + '|' + intensity;
  if (!matCache.has(key)) {
    matCache.set(key, new THREE.MeshStandardMaterial({
      color,
      emissive: color,
      emissiveIntensity: intensity,
      roughness: 0.32,
      metalness: 0.0,
      side: THREE.DoubleSide,
    }));
  }
  return matCache.get(key);
}

import * as THREE from 'three';
import { STAMPS } from './data.js';
import {
  starShape, heartShape, moonShape, ellipseShape, batWingShape, glowMaterial,
} from './shapes.js';

function flat(shape, material, scale = 1) {
  const g = new THREE.ShapeGeometry(shape, 18);
  const m = new THREE.Mesh(g, material);
  m.scale.setScalar(scale);
  return m;
}

/**
 * Builds a little glowing charm lying in the XY plane, facing +Z.
 * Real charms are ~0.22 world units wide before the group scale is applied.
 */
export function createCharm(type, { ghost = false, scale = 1 } = {}) {
  const info = STAMPS[type] || STAMPS.star;
  const group = new THREE.Group();
  const mat = ghost
    ? new THREE.MeshBasicMaterial({ color: info.glow, transparent: true, opacity: 0.5, depthWrite: false })
    : glowMaterial(info.color, 1.75);
  const softMat = ghost
    ? mat
    : glowMaterial(info.glow, 0.7);
  const whiteMat = ghost
    ? mat
    : new THREE.MeshBasicMaterial({ color: '#fff9ee' });

  if (type === 'star') {
    group.add(flat(starShape(1, 0.45, 5), mat));
    const dot = flat(ellipseShape(0.12, 0.12), whiteMat);
    dot.position.set(0.22, 0.24, 0.012);
    group.add(dot);
  } else if (type === 'heart') {
    group.add(flat(heartShape(), mat));
    const shine = flat(ellipseShape(0.12, 0.19), whiteMat);
    shine.position.set(-0.32, 0.3, 0.012);
    shine.rotation.z = 0.6;
    group.add(shine);
  } else if (type === 'moon') {
    group.add(flat(moonShape(), mat));
    const c1 = flat(ellipseShape(0.13, 0.13), softMat);
    c1.position.set(-0.06, 0.3, 0.012);
    const c2 = flat(ellipseShape(0.08, 0.08), softMat);
    c2.position.set(-0.22, -0.18, 0.012);
    group.add(c1, c2);
  } else if (type === 'flower') {
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * Math.PI * 2;
      const petal = flat(ellipseShape(0.34, 0.5), mat);
      petal.position.set(Math.cos(a) * 0.4, Math.sin(a) * 0.4, 0);
      petal.rotation.z = a - Math.PI / 2;
      group.add(petal);
    }
    group.add(flat(ellipseShape(0.26, 0.26), ghost ? mat : glowMaterial('#fff0c9', 1.1)));
  } else if (type === 'bat') {
    const wingL = flat(batWingShape(false), mat);
    wingL.scale.setScalar(0.9);
    wingL.position.set(0, -0.02, 0);
    const wingR = flat(batWingShape(true), mat);
    wingR.scale.setScalar(0.9);
    wingR.position.set(0, -0.02, 0);
    const body = flat(ellipseShape(0.15, 0.4), mat);
    body.position.set(0, -0.04, 0.002);
    const eyeL = flat(ellipseShape(0.045, 0.06), whiteMat);
    eyeL.position.set(-0.07, 0.12, 0.015);
    const eyeR = eyeL.clone();
    eyeR.position.x = 0.07;
    group.add(wingL, wingR, body, eyeL, eyeR);
  } else {
    group.add(flat(starShape(), mat));
  }

  group.scale.setScalar(scale);
  group.traverse((o) => {
    if (o.isMesh) o.renderOrder = 2;
  });
  return group;
}

import * as THREE from 'three';
import { PALETTES, FACES, ACCESSORIES, STAMPS, STAMP_LIMIT } from './data.js';
import {
  starShape, heartShape, ellipseShape, triangleShape, zigzagShape, batWingShape,
  glowMaterial,
} from './shapes.js';
import { createCharm } from './charms.js';

const DEG = Math.PI / 180;
const _up = new THREE.Vector3(0, 1, 0);

export function deformDirection(v) {
  const lon = Math.atan2(v.z, v.x);
  const rib = 1 + 0.048 * Math.cos(lon * 8);
  const out = new THREE.Vector3(v.x * 0.96 * rib, v.y * 0.78, v.z * 0.96 * rib);
  const ay = Math.min(1, Math.abs(v.y));
  const pinch = 1 - 0.1 * Math.pow(ay, 8);
  out.x *= pinch;
  out.z *= pinch;
  return out;
}

function directionFromAngles(lonDeg, latDeg) {
  const lon = lonDeg * DEG;
  const lat = latDeg * DEG;
  return new THREE.Vector3(
    Math.sin(lon) * Math.cos(lat),
    Math.sin(lat),
    Math.cos(lon) * Math.cos(lat),
  ).normalize();
}

function basisQuaternion(normal, roll = 0) {
  const n = normal.clone().normalize();
  const up = Math.abs(n.dot(_up)) > 0.97 ? new THREE.Vector3(0, 0, 1) : _up;
  const right = new THREE.Vector3().crossVectors(up, n).normalize();
  const realUp = new THREE.Vector3().crossVectors(n, right).normalize();
  const m = new THREE.Matrix4().makeBasis(right, realUp, n);
  const q = new THREE.Quaternion().setFromRotationMatrix(m);
  if (roll) q.multiply(new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 0, 1), roll));
  return q;
}

function ringArc(inner, outer, start, length) {
  return new THREE.RingGeometry(inner, outer, 30, 1, start, length);
}

export class Pumpkin {
  constructor(scene) {
    this.root = new THREE.Group();
    this.root.position.set(0, 1.34, 0);
    scene.add(this.root);

    this.paletteKey = 'ember';
    this.faceKey = 'happy';
    this.accessoryKey = 'none';
    this.stamps = [];
    this.pulse = 0;

    this._buildBody();
    this._buildStem();

    this.faceGroup = new THREE.Group();
    this.root.add(this.faceGroup);

    this.accessoryGroup = new THREE.Group();
    this.root.add(this.accessoryGroup);

    this.stampGroup = new THREE.Group();
    this.root.add(this.stampGroup);

    this.faceMat = new THREE.MeshStandardMaterial({
      color: '#351426',
      emissive: '#ffd36e',
      emissiveIntensity: 2.2,
      roughness: 0.35,
      metalness: 0,
    });
    this.socketMat = new THREE.MeshStandardMaterial({
      color: '#2a0f1f',
      roughness: 0.95,
      metalness: 0,
    });
    this.blushMat = new THREE.MeshStandardMaterial({
      color: '#ff7fae',
      emissive: '#ff5c9a',
      emissiveIntensity: 0.45,
      roughness: 0.8,
    });

    this.faceLight = new THREE.PointLight('#ffcf6e', 2.2, 4.2, 2);
    this.faceLight.position.set(0, 0.1, 0.35);
    this.root.add(this.faceLight);

    this.setFace('happy');
    this.setAccessory('none');

    // ghost preview for the stamping mechanic
    this.previewRoot = new THREE.Group();
    this.previewRoot.visible = false;
    this.root.add(this.previewRoot);
    this.previewType = null;
    this.previewMirror = false;

    this.raycaster = new THREE.Raycaster();
  }

  _buildBody() {
    const geo = new THREE.SphereGeometry(1, 128, 80);
    const pos = geo.attributes.position;
    const v = new THREE.Vector3();
    const colors = new Float32Array(pos.count * 3);
    for (let i = 0; i < pos.count; i++) {
      v.fromBufferAttribute(pos, i).normalize();
      const d = deformDirection(v);
      pos.setXYZ(i, d.x, d.y, d.z);
      const lon = Math.atan2(v.z, v.x);
      const ridge = 0.5 + 0.5 * Math.cos(lon * 8);
      const shade = 0.8 + 0.2 * ridge;
      const grad = 0.78 + 0.28 * (v.y * 0.5 + 0.5);
      const speck = 1 + 0.02 * Math.sin(v.x * 42) * Math.sin(v.y * 31 + 1.4);
      const c = Math.min(1.04, shade * grad * speck);
      colors[i * 3] = c;
      colors[i * 3 + 1] = c;
      colors[i * 3 + 2] = c;
    }
    geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    geo.computeVertexNormals();

    const pal = PALETTES[this.paletteKey];
    this.bodyMat = new THREE.MeshPhysicalMaterial({
      vertexColors: true,
      color: pal.body,
      emissive: pal.dark,
      emissiveIntensity: 0.08,
      roughness: 0.44,
      metalness: 0,
      clearcoat: 0.45,
      clearcoatRoughness: 0.6,
      sheen: 0.7,
      sheenColor: new THREE.Color(pal.accent),
      sheenRoughness: 0.55,
    });
    this.body = new THREE.Mesh(geo, this.bodyMat);
    this.body.castShadow = true;
    this.body.receiveShadow = true;
    this.root.add(this.body);
  }

  _buildStem() {
    this.stemGroup = new THREE.Group();
    const stemMat = new THREE.MeshStandardMaterial({
      color: '#7d4a28', roughness: 0.9, metalness: 0,
    });
    const curve = new THREE.CatmullRomCurve3([
      new THREE.Vector3(0, 0.74, 0),
      new THREE.Vector3(0.03, 0.87, 0.01),
      new THREE.Vector3(0.1, 0.98, 0.02),
      new THREE.Vector3(0.06, 1.08, 0.05),
    ]);
    const stem = new THREE.Mesh(new THREE.TubeGeometry(curve, 20, 0.06, 10, false), stemMat);
    stem.castShadow = true;
    this.stemGroup.add(stem);

    const cap = new THREE.Mesh(new THREE.SphereGeometry(0.075, 12, 10), stemMat);
    cap.position.copy(curve.getPoint(1));
    this.stemGroup.add(cap);

    const vineMat = new THREE.MeshStandardMaterial({ color: '#5e9b5c', roughness: 0.8 });
    const vineCurve = new THREE.CatmullRomCurve3([
      new THREE.Vector3(0.04, 0.8, 0.02),
      new THREE.Vector3(0.22, 0.86, 0.08),
      new THREE.Vector3(0.34, 0.72, 0.14),
      new THREE.Vector3(0.27, 0.56, 0.2),
      new THREE.Vector3(0.36, 0.48, 0.24),
    ]);
    const vine = new THREE.Mesh(new THREE.TubeGeometry(vineCurve, 30, 0.014, 6, false), vineMat);
    this.stemGroup.add(vine);

    const leafShape = new THREE.Shape();
    leafShape.moveTo(0, 0);
    leafShape.quadraticCurveTo(0.1, 0.08, 0.02, 0.2);
    leafShape.quadraticCurveTo(-0.08, 0.1, 0, 0);
    const leafGeo = new THREE.ShapeGeometry(leafShape);
    const leaf = new THREE.Mesh(leafGeo, vineMat);
    leaf.position.set(0.35, 0.62, 0.19);
    leaf.rotation.set(0.2, 0.4, 0.3);
    leaf.scale.setScalar(1.4);
    this.stemGroup.add(leaf);

    this.root.add(this.stemGroup);
  }

  // ---------- placement helpers ----------

  surfacePoint(lonDeg, latDeg, offset = 0) {
    const dir = directionFromAngles(lonDeg, latDeg);
    const p = deformDirection(dir);
    p.addScaledVector(dir, offset);
    return { point: p, dir };
  }

  placeObject(obj, lonDeg, latDeg, offset = 0.015, roll = 0) {
    const { point, dir } = this.surfacePoint(lonDeg, latDeg, offset);
    obj.position.copy(point);
    obj.quaternion.copy(basisQuaternion(dir, roll));
  }

  // ---------- palette / face / accessory ----------

  setPalette(key) {
    if (!PALETTES[key]) return;
    this.paletteKey = key;
    const pal = PALETTES[key];
    this.bodyMat.color.set(pal.body);
    this.bodyMat.emissive.set(pal.dark);
    this.bodyMat.sheenColor.set(pal.accent);
  }

  setFace(key) {
    if (!FACES[key]) return;
    this.faceKey = key;
    const face = FACES[key];
    this.faceGroup.clear();
    this.faceMat.emissive.set(face.glow);
    this.faceLight.color.set(face.glow);

    const glow = this.faceMat;
    const socket = this.socketMat;

    const addPiece = (geometry, lon, lat, sx, sy, roll = 0, offset = 0.03) => {
      const s = new THREE.Mesh(geometry, socket);
      s.scale.set(sx * 1.24, sy * 1.24, 1);
      this.placeObject(s, lon, lat, offset - 0.009, roll);
      this.faceGroup.add(s);

      const m = new THREE.Mesh(geometry, glow);
      m.scale.set(sx, sy, 1);
      this.placeObject(m, lon, lat, offset, roll);
      this.faceGroup.add(m);
      return m;
    };

    const eyeLon = 15.5;
    const eyeLat = 9;
    const blush = (lon, lat) => {
      const b = new THREE.Mesh(new THREE.SphereGeometry(1, 20, 14), this.blushMat);
      b.scale.set(0.115, 0.07, 0.02);
      this.placeObject(b, lon, lat, 0.012);
      this.faceGroup.add(b);
    };

    const addGlint = (eye, x, y, size = 0.13) => {
      const glint = new THREE.Mesh(
        new THREE.ShapeGeometry(ellipseShape(size, size), 10),
        new THREE.MeshBasicMaterial({ color: '#fff8e8' }),
      );
      glint.position.set(x, y, 0.03);
      eye.add(glint);
    };

    if (key === 'happy') {
      const eyeGeo = new THREE.ShapeGeometry(ellipseShape(0.5, 0.5), 20);
      const l = addPiece(eyeGeo, -eyeLon, eyeLat, 0.18, 0.22);
      const r = addPiece(eyeGeo, eyeLon, eyeLat, 0.18, 0.22);
      addGlint(l, -0.16, 0.2, 0.15);
      addGlint(r, -0.16, 0.2, 0.15);
      const mouth = ringArc(0.3, 0.5, Math.PI * 1.12, Math.PI * 0.76);
      addPiece(mouth, 0, -18, 0.4, 0.34, 0, 0.035);
      blush(-29, -7);
      blush(29, -7);
    } else if (key === 'sleepy') {
      const arc = ringArc(0.3, 0.5, Math.PI * 0.12, Math.PI * 0.76);
      addPiece(arc, -eyeLon, eyeLat + 1, 0.4, 0.3);
      addPiece(arc, eyeLon, eyeLat + 1, 0.4, 0.3);
      const o = new THREE.TorusGeometry(0.1, 0.032, 8, 18);
      addPiece(o, 0, -18, 1.05, 1.05, 0, 0.04);
      blush(-30, -6);
      blush(30, -6);
      // tiny sleepy z
      const zGeo = new THREE.BufferGeometry().setFromPoints([
        new THREE.Vector3(-0.03, 0.05, 0), new THREE.Vector3(0.03, 0.05, 0),
        new THREE.Vector3(-0.03, -0.05, 0), new THREE.Vector3(0.03, -0.05, 0),
      ]);
      const z = new THREE.Line(zGeo, new THREE.LineBasicMaterial({ color: '#ffe9bd' }));
      z.position.set(0.12, 0.34, 0.01);
      this.faceGroup.add(z);
    } else if (key === 'wink') {
      const eyeGeo = new THREE.ShapeGeometry(ellipseShape(0.5, 0.5), 20);
      const l = addPiece(eyeGeo, -eyeLon, eyeLat, 0.18, 0.22);
      addGlint(l, -0.16, 0.2, 0.15);
      const arc = ringArc(0.3, 0.5, Math.PI * 0.12, Math.PI * 0.76);
      addPiece(arc, eyeLon, eyeLat + 1, 0.4, 0.3);
      const mouth = ringArc(0.3, 0.5, Math.PI * 1.12, Math.PI * 0.76);
      addPiece(mouth, 3, -18, 0.36, 0.32, 0.12, 0.035);
      blush(-29, -7);
      blush(29, -7);
    } else if (key === 'cat') {
      const eyeGeo = new THREE.ShapeGeometry(ellipseShape(0.5, 0.5), 20);
      const l = addPiece(eyeGeo, -eyeLon, eyeLat, 0.17, 0.22);
      const r = addPiece(eyeGeo, eyeLon, eyeLat, 0.17, 0.22);
      addGlint(l, -0.14, 0.18, 0.13);
      addGlint(r, -0.14, 0.18, 0.13);
      const slit = new THREE.ShapeGeometry(ellipseShape(0.16, 0.5), 12);
      const slitMat = new THREE.MeshBasicMaterial({ color: '#3a1226' });
      for (const eye of [l, r]) {
        const s = new THREE.Mesh(slit, slitMat);
        s.position.set(0, 0, 0.025);
        eye.add(s);
      }
      const nose = new THREE.Mesh(new THREE.ShapeGeometry(triangleShape(0.5, 0.5)), glowMaterial('#ff9ec9', 1.2));
      this.placeObject(nose, 0, -11.5, 0.045);
      nose.rotateZ(Math.PI);
      nose.scale.setScalar(0.055);
      this.faceGroup.add(nose);
      const arc = ringArc(0.3, 0.5, Math.PI * 1.12, Math.PI * 0.76);
      addPiece(arc, -4.5, -18, 0.18, 0.16, 0, 0.035);
      addPiece(arc, 4.5, -18, 0.18, 0.16, 0, 0.035);
      blush(-29, -8);
      blush(29, -8);
    } else if (key === 'spooky') {
      const tri = new THREE.ShapeGeometry(triangleShape(0.5, 0.5), 4);
      addPiece(tri, -16, 10, 0.2, 0.22, -0.1);
      addPiece(tri, 16, 10, 0.2, 0.22, 0.1);
      const zig = new THREE.ShapeGeometry(zigzagShape(0.9, 0.3, 5), 4);
      addPiece(zig, 0, -19, 0.34, 0.24, 0, 0.04);
    }

    this.faceGroup.traverse((o) => {
      if (o.isMesh) o.castShadow = false;
    });
  }

  setAccessory(key) {
    if (!ACCESSORIES[key]) return;
    this.accessoryKey = key;
    this.accessoryGroup.clear();
    this.wings = null;

    if (key === 'witch') {
      const g = new THREE.Group();
      g.position.set(0, 0.8, 0);
      g.rotation.set(0.06, 0, -0.11);

      const felt = new THREE.MeshStandardMaterial({ color: '#5c3fae', roughness: 0.72 });
      const feltDark = new THREE.MeshStandardMaterial({ color: '#432c86', roughness: 0.8 });
      const gold = new THREE.MeshStandardMaterial({
        color: '#ffd36e', emissive: '#ffb62e', emissiveIntensity: 0.5, roughness: 0.35, metalness: 0.3,
      });

      const brim = new THREE.Mesh(new THREE.CylinderGeometry(0.66, 0.7, 0.055, 48), feltDark);
      brim.position.y = 0.02;
      brim.castShadow = true;
      g.add(brim);

      const cone = new THREE.Mesh(new THREE.ConeGeometry(0.34, 0.86, 40), felt);
      cone.position.y = 0.47;
      cone.rotation.z = 0.05;
      cone.castShadow = true;
      g.add(cone);

      const tip = new THREE.Mesh(new THREE.ConeGeometry(0.12, 0.3, 24), felt);
      tip.position.set(0.1, 0.92, 0);
      tip.rotation.z = -0.35;
      tip.castShadow = true;
      g.add(tip);

      const band = new THREE.Mesh(new THREE.CylinderGeometry(0.335, 0.37, 0.13, 40), gold);
      band.position.y = 0.12;
      g.add(band);

      const buckle = new THREE.Mesh(new THREE.ShapeGeometry(starShape(1, 0.45, 5)), gold);
      buckle.position.set(0, 0.12, 0.36);
      buckle.scale.setScalar(0.075);
      g.add(buckle);

      const bobble = new THREE.Mesh(new THREE.SphereGeometry(0.055, 12, 10), gold);
      bobble.position.set(0.19, 1.03, 0);
      g.add(bobble);

      this.accessoryGroup.add(g);
      this.hatGroup = g;
    } else if (key === 'bow') {
      const g = new THREE.Group();
      const pink = new THREE.MeshStandardMaterial({
        color: '#ff8fba', roughness: 0.55, sheen: 0.6, sheenColor: new THREE.Color('#ffd6e6'),
      });
      const cream = new THREE.MeshStandardMaterial({ color: '#ffe9c9', roughness: 0.6 });

      const loopGeo = new THREE.SphereGeometry(1, 20, 14);
      const l = new THREE.Mesh(loopGeo, pink);
      l.scale.set(0.23, 0.15, 0.075);
      l.position.set(-0.17, 0.03, 0);
      l.rotation.z = 0.42;
      const r = new THREE.Mesh(loopGeo, pink);
      r.scale.set(0.23, 0.15, 0.075);
      r.position.set(0.17, 0.03, 0);
      r.rotation.z = -0.42;

      const knot = new THREE.Mesh(new THREE.SphereGeometry(0.095, 16, 12), cream);
      knot.position.z = 0.02;

      const tailGeo = new THREE.SphereGeometry(1, 14, 10);
      const t1 = new THREE.Mesh(tailGeo, pink);
      t1.scale.set(0.06, 0.17, 0.035);
      t1.position.set(-0.08, -0.18, -0.01);
      t1.rotation.z = 0.22;
      const t2 = new THREE.Mesh(tailGeo, pink);
      t2.scale.set(0.06, 0.17, 0.035);
      t2.position.set(0.08, -0.18, -0.01);
      t2.rotation.z = -0.22;

      g.add(l, r, knot, t1, t2);
      g.traverse((o) => { if (o.isMesh) o.castShadow = true; });
      this.placeObject(g, 38, 52, 0.1, -0.25);
      this.accessoryGroup.add(g);
    } else if (key === 'crown') {
      const g = new THREE.Group();
      const ring = new THREE.Mesh(
        new THREE.TorusGeometry(0.53, 0.016, 8, 64),
        new THREE.MeshStandardMaterial({ color: '#ffd36e', emissive: '#ffb62e', emissiveIntensity: 0.6, roughness: 0.3, metalness: 0.4 }),
      );
      ring.rotation.x = Math.PI / 2;
      ring.position.y = 0.64;
      g.add(ring);

      const petalMat = new THREE.MeshStandardMaterial({
        color: '#ffb3cf', emissive: '#ff7fae', emissiveIntensity: 0.18, roughness: 0.6,
      });
      const petalMat2 = new THREE.MeshStandardMaterial({ color: '#fff0c9', roughness: 0.55 });
      const leafMat = new THREE.MeshStandardMaterial({ color: '#71c48f', roughness: 0.7 });

      const petalGeo = new THREE.SphereGeometry(0.045, 10, 8);
      const centerGeo = new THREE.SphereGeometry(0.032, 10, 8);
      for (let i = 0; i < 8; i++) {
        const lon = (i / 8) * 360 + 22;
        const lat = 56;
        const { point, dir } = this.surfacePoint(lon, lat, 0.03);
        const flower = new THREE.Group();
        flower.position.copy(point);
        flower.quaternion.copy(basisQuaternion(dir));
        for (let p = 0; p < 5; p++) {
          const a = (p / 5) * Math.PI * 2;
          const petal = new THREE.Mesh(petalGeo, i % 2 ? petalMat : petalMat2);
          petal.position.set(Math.cos(a) * 0.05, Math.sin(a) * 0.05, 0);
          petal.scale.set(1, 1.3, 0.5);
          flower.add(petal);
        }
        const heart = new THREE.Mesh(centerGeo, petalMat2);
        heart.position.z = 0.015;
        flower.add(heart);
        g.add(flower);

        const leaf = new THREE.Mesh(petalGeo, leafMat);
        leaf.scale.set(0.6, 1.4, 0.3);
        const lp = this.surfacePoint(lon + 22, lat - 2, 0.02);
        leaf.position.copy(lp.point);
        leaf.quaternion.copy(basisQuaternion(lp.dir, 0.8));
        g.add(leaf);
      }
      g.traverse((o) => { if (o.isMesh) o.castShadow = true; });
      this.accessoryGroup.add(g);
    } else if (key === 'ears') {
      const g = new THREE.Group();
      const dark = new THREE.MeshStandardMaterial({ color: '#4b3568', roughness: 0.7 });
      const pink = new THREE.MeshStandardMaterial({ color: '#ffa5c4', roughness: 0.6 });
      for (const side of [-1, 1]) {
        const { point } = this.surfacePoint(side * 36, 52, 0.02);
        const ear = new THREE.Group();
        ear.position.copy(point);
        ear.rotation.z = side * -0.28;
        ear.rotation.x = -0.08;
        const outer = new THREE.Mesh(new THREE.ConeGeometry(0.19, 0.38, 4), dark);
        outer.position.y = 0.17;
        outer.rotation.y = Math.PI / 4;
        outer.castShadow = true;
        const inner = new THREE.Mesh(new THREE.ConeGeometry(0.11, 0.24, 4), pink);
        inner.position.set(0, 0.13, 0.05);
        inner.rotation.y = Math.PI / 4;
        ear.add(outer, inner);
        g.add(ear);
      }
      this.accessoryGroup.add(g);
    } else if (key === 'wings') {
      const g = new THREE.Group();
      const wingMat = new THREE.MeshStandardMaterial({
        color: '#4a2f7a', emissive: '#7b4dd6', emissiveIntensity: 0.35,
        roughness: 0.55, side: THREE.DoubleSide,
      });
      const wingGeo = new THREE.ShapeGeometry(batWingShape(false), 20);
      const pivots = [];
      for (const side of [-1, 1]) {
        const pivot = new THREE.Group();
        pivot.position.set(side * 0.45, 0.12, -0.42);
        const wing = new THREE.Mesh(wingGeo, wingMat);
        wing.scale.set(side * 1.05, 1.05, 1);
        wing.position.set(side * 0.4, 0, 0);
        wing.castShadow = true;
        pivot.add(wing);
        pivot.rotation.y = side * 0.55;
        pivot.rotation.z = side * -0.15;
        g.add(pivot);
        pivots.push(pivot);
      }
      this.wings = pivots;
      this.accessoryGroup.add(g);
    }
  }

  // ---------- glow stamps ----------

  addStamp(type, localPoint, localNormal, { roll = Math.random() * Math.PI * 2, mirror = false } = {}) {
    if (!STAMPS[type]) return null;
    if (this.stamps.length >= STAMP_LIMIT) return 'full';
    const scale = 0.135 * (0.9 + Math.random() * 0.25);
    const charm = createCharm(type, { scale });
    const normal = localNormal.clone().normalize();
    charm.position.copy(localPoint).addScaledVector(normal, 0.022);
    charm.quaternion.copy(basisQuaternion(normal, roll));
    charm.userData.baseScale = scale;
    charm.scale.setScalar(0.0001);
    this.stampGroup.add(charm);

    const entry = { group: charm, type, spawn: 0, roll };
    this.stamps.push(entry);
    this.pulse = 1;

    if (mirror) {
      const mPoint = new THREE.Vector3(-localPoint.x, localPoint.y, localPoint.z);
      const mNormal = new THREE.Vector3(-normal.x, normal.y, normal.z).normalize();
      const mCharm = createCharm(type, { scale });
      mCharm.position.copy(mPoint).addScaledVector(mNormal, 0.022);
      mCharm.quaternion.copy(basisQuaternion(mNormal, -roll));
      mCharm.userData.baseScale = scale;
      mCharm.scale.setScalar(0.0001);
      this.stampGroup.add(mCharm);
      this.stamps.push({ group: mCharm, type, spawn: 0, roll: -roll });
    }

    this.refreshPreview();
    return entry;
  }

  undoStamp() {
    const entry = this.stamps.pop();
    if (!entry) return false;
    this.stampGroup.remove(entry.group);
    return true;
  }

  clearStamps() {
    this.stamps.forEach((s) => this.stampGroup.remove(s.group));
    this.stamps.length = 0;
  }

  stampCounts() {
    const counts = {};
    for (const s of this.stamps) counts[s.type] = (counts[s.type] || 0) + 1;
    return counts;
  }

  // ---------- preview ----------

  setPreview(type, localPoint, localNormal, mirror) {
    if (!type) { this.previewRoot.visible = false; return; }
    if (this.previewType !== type || this.previewMirror !== mirror) {
      this.previewRoot.clear();
      this.previewType = type;
      this.previewMirror = mirror;
      const scale = 0.135;
      const a = createCharm(type, { ghost: true, scale });
      this.previewRoot.add(a);
      if (mirror) {
        const b = createCharm(type, { ghost: true, scale });
        this.previewRoot.add(b);
      }
    }
    const normal = localNormal.clone().normalize();
    const a = this.previewRoot.children[0];
    a.position.copy(localPoint).addScaledVector(normal, 0.026);
    a.quaternion.copy(basisQuaternion(normal, 0.3));
    if (mirror && this.previewRoot.children[1]) {
      const b = this.previewRoot.children[1];
      const mp = new THREE.Vector3(-localPoint.x, localPoint.y, localPoint.z);
      const mn = new THREE.Vector3(-normal.x, normal.y, normal.z).normalize();
      b.position.copy(mp).addScaledVector(mn, 0.026);
      b.quaternion.copy(basisQuaternion(mn, -0.3));
    }
    this.previewRoot.visible = true;
  }

  hidePreview() {
    this.previewRoot.visible = false;
  }

  refreshPreview() {
    // preview material/state stays; nothing to do but keep API tidy
  }

  // ---------- raycasting ----------

  raycast(raycaster) {
    const hits = raycaster.intersectObject(this.body, false);
    return hits.length ? hits[0] : null;
  }

  getStats() {
    return {
      palette: this.paletteKey,
      face: this.faceKey,
      accessory: this.accessoryKey,
      counts: this.stampCounts(),
      totalStamps: this.stamps.length,
    };
  }

  update(dt, t) {
    this.pulse = Math.max(0, this.pulse - dt * 3.2);
    const p = 1 + this.pulse * 0.028;
    this.body.scale.set(p, 1 + this.pulse * 0.012, p);

    this.stemGroup.rotation.z = Math.sin(t * 1.1) * 0.018;
    this.stemGroup.rotation.x = Math.cos(t * 0.9) * 0.012;

    this.faceLight.intensity = 2.0 + Math.sin(t * 2.3) * 0.18 + Math.sin(t * 7.1) * 0.06;

    for (const s of this.stamps) {
      if (s.spawn < 1) {
        s.spawn = Math.min(1, s.spawn + dt * 4.2);
        const e = 1 - Math.pow(1 - s.spawn, 3);
        const overshoot = 1 + Math.sin(s.spawn * Math.PI) * 0.22;
        s.group.scale.setScalar(s.group.userData.baseScale * e * overshoot);
      }
    }

    if (this.wings) {
      const flap = Math.sin(t * 2.6) * 0.16;
      this.wings[0].rotation.z = -0.15 + flap;
      this.wings[1].rotation.z = 0.15 - flap;
    }
    if (this.hatGroup) {
      this.hatGroup.rotation.z = -0.11 + Math.sin(t * 1.4) * 0.018;
    }
  }
}

import * as THREE from 'three';

function makeRadialTexture(inner = 'rgba(255,240,200,1)', outer = 'rgba(255,200,120,0)', size = 128) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0, inner);
  g.addColorStop(0.35, inner.replace(/[\d.]+\)$/, '0.55)'));
  g.addColorStop(1, outer);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function makeMoonTexture() {
  const c = document.createElement('canvas');
  c.width = 256; c.height = 256;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#fff3d4';
  ctx.fillRect(0, 0, 256, 256);
  const craters = [
    [70, 90, 22], [160, 70, 14], [190, 160, 26], [100, 175, 12], [50, 180, 9], [140, 130, 18],
  ];
  for (const [x, y, r] of craters) {
    const g = ctx.createRadialGradient(x - r * 0.3, y - r * 0.3, 0, x, y, r);
    g.addColorStop(0, 'rgba(226,206,170,0.55)');
    g.addColorStop(1, 'rgba(226,206,170,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
  }
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function miniPumpkinGeometry() {
  const geo = new THREE.SphereGeometry(1, 40, 26);
  const pos = geo.attributes.position;
  const v = new THREE.Vector3();
  for (let i = 0; i < pos.count; i++) {
    v.fromBufferAttribute(pos, i).normalize();
    const lon = Math.atan2(v.z, v.x);
    const rib = 1 + 0.07 * Math.cos(lon * 8);
    pos.setXYZ(i, v.x * 0.95 * rib, v.y * 0.7, v.z * 0.95 * rib);
  }
  geo.computeVertexNormals();
  return geo;
}

function buildMiniPumpkin(color, scale = 1) {
  const g = new THREE.Group();
  const body = new THREE.Mesh(
    miniPumpkinGeometry(),
    new THREE.MeshStandardMaterial({ color, roughness: 0.55, sheen: 0.5, sheenColor: new THREE.Color('#ffd6b0') }),
  );
  body.castShadow = true;
  body.receiveShadow = true;
  body.scale.setScalar(scale);
  g.add(body);
  const stem = new THREE.Mesh(
    new THREE.CylinderGeometry(0.04 * scale, 0.06 * scale, 0.16 * scale, 6),
    new THREE.MeshStandardMaterial({ color: '#6d4a2c', roughness: 0.9 }),
  );
  stem.position.y = 0.68 * scale;
  stem.rotation.z = 0.15;
  g.add(stem);
  return g;
}

function buildTree(scale = 1) {
  const g = new THREE.Group();
  const trunkMat = new THREE.MeshStandardMaterial({ color: '#2a1c3a', roughness: 0.95 });
  const leafMat = new THREE.MeshStandardMaterial({ color: '#241a3c', roughness: 0.95 });
  const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.16 * scale, 0.24 * scale, 2.2 * scale, 8), trunkMat);
  trunk.position.y = 1.1 * scale;
  g.add(trunk);
  for (let i = 0; i < 3; i++) {
    const cone = new THREE.Mesh(new THREE.ConeGeometry((1.1 - i * 0.26) * scale, 1.5 * scale, 9), leafMat);
    cone.position.y = (2.2 + i * 0.7) * scale;
    cone.rotation.y = i * 0.5;
    g.add(cone);
  }
  return g;
}

function buildFence() {
  const g = new THREE.Group();
  const mat = new THREE.MeshStandardMaterial({ color: '#3b2a45', roughness: 0.9 });
  for (let x = -8; x <= 8; x += 1.6) {
    const post = new THREE.Mesh(new THREE.BoxGeometry(0.16, 1.2, 0.16), mat);
    post.position.set(x, 0.6, 0);
    g.add(post);
  }
  for (const y of [0.45, 0.95]) {
    const rail = new THREE.Mesh(new THREE.BoxGeometry(16.4, 0.12, 0.1), mat);
    rail.position.set(0, y, 0.02);
    g.add(rail);
  }
  g.position.set(0, 0, -7.5);
  return g;
}

function buildStringLights(scene) {
  const bulbGeo = new THREE.SphereGeometry(0.055, 10, 8);
  const bulbMat = new THREE.MeshBasicMaterial({ color: '#ffd98a' });
  const wireMat = new THREE.MeshStandardMaterial({ color: '#1d1428', roughness: 1 });
  const colors = ['#ffd98a', '#ffb3d1', '#bcd7ff', '#ffd98a'];

  for (const [z, y0, y1, sway] of [[-3.6, 3.0, 3.2, 0.9], [-5.6, 3.6, 3.8, 1.3]]) {
    const pts = [];
    for (let i = 0; i <= 10; i++) {
      const x = -5.2 + (i / 10) * 10.4;
      const sag = Math.sin((i / 10) * Math.PI) * sway;
      pts.push(new THREE.Vector3(x, y0 + (y1 - y0) * (i / 10) - sag, z));
    }
    const curve = new THREE.CatmullRomCurve3(pts);
    const wire = new THREE.Mesh(new THREE.TubeGeometry(curve, 40, 0.012, 5, false), wireMat);
    scene.add(wire);
    for (let i = 1; i < 10; i++) {
      const p = curve.getPoint(i / 10);
      const bulb = new THREE.Mesh(bulbGeo, new THREE.MeshBasicMaterial({ color: colors[i % colors.length] }));
      bulb.position.copy(p).add(new THREE.Vector3(0, -0.07, 0));
      bulb.scale.setScalar(0.9 + Math.random() * 0.3);
      scene.add(bulb);
    }
  }

  const warm = new THREE.PointLight('#ffb367', 12, 14, 2);
  warm.position.set(0, 2.8, -4.2);
  scene.add(warm);
}

export function createWorld(scene, renderer) {
  scene.fog = new THREE.FogExp2('#1a1130', 0.026);

  // ----- sky dome -----
  const skyGeo = new THREE.SphereGeometry(70, 40, 24);
  const skyMat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    uniforms: {
      top: { value: new THREE.Color('#0a0718') },
      horizon: { value: new THREE.Color('#3c2358') },
      bottom: { value: new THREE.Color('#170e26') },
      moonGlow: { value: new THREE.Color('#5b3f7d') },
    },
    vertexShader: `
      varying vec3 vPos;
      void main() {
        vPos = position;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      varying vec3 vPos;
      uniform vec3 top;
      uniform vec3 horizon;
      uniform vec3 bottom;
      uniform vec3 moonGlow;
      void main() {
        vec3 d = normalize(vPos);
        float h = clamp(d.y * 0.5 + 0.5, 0.0, 1.0);
        vec3 c = mix(bottom, horizon, smoothstep(0.3, 0.52, h));
        c = mix(c, top, smoothstep(0.52, 0.95, h));
        float moon = pow(max(dot(d, normalize(vec3(-0.34, 0.5, -0.8))), 0.0), 8.0);
        c += moonGlow * moon * 0.55;
        gl_FragColor = vec4(c, 1.0);
      }
    `,
  });
  const sky = new THREE.Mesh(skyGeo, skyMat);
  scene.add(sky);

  // ----- stars -----
  const starCount = 750;
  const starPos = new Float32Array(starCount * 3);
  const starSize = new Float32Array(starCount);
  for (let i = 0; i < starCount; i++) {
    const a = Math.random() * Math.PI * 2;
    const y = Math.pow(Math.random(), 0.7) * 0.95 + 0.05;
    const r = Math.sqrt(1 - y * y);
    starPos[i * 3] = Math.cos(a) * r * 50;
    starPos[i * 3 + 1] = y * 50;
    starPos[i * 3 + 2] = Math.sin(a) * r * 50;
    starSize[i] = 0.4 + Math.random() * 1.6;
  }
  const starGeo = new THREE.BufferGeometry();
  starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
  starGeo.setAttribute('aSize', new THREE.BufferAttribute(starSize, 1));
  const starMat = new THREE.ShaderMaterial({
    transparent: true,
    depthWrite: false,
    uniforms: { uTime: { value: 0 } },
    vertexShader: `
      attribute float aSize;
      uniform float uTime;
      varying float vTwinkle;
      void main() {
        vTwinkle = 0.55 + 0.45 * sin(uTime * 1.5 + aSize * 40.0);
        vec4 mv = modelViewMatrix * vec4(position, 1.0);
        gl_PointSize = aSize * 2.4;
        gl_Position = projectionMatrix * mv;
      }
    `,
    fragmentShader: `
      varying float vTwinkle;
      void main() {
        float d = distance(gl_PointCoord, vec2(0.5));
        if (d > 0.5) discard;
        float a = smoothstep(0.5, 0.05, d) * vTwinkle;
        gl_FragColor = vec4(0.95, 0.92, 1.0, a);
      }
    `,
  });
  const stars = new THREE.Points(starGeo, starMat);
  scene.add(stars);

  // ----- moon -----
  const moon = new THREE.Mesh(
    new THREE.SphereGeometry(1.7, 32, 24),
    new THREE.MeshBasicMaterial({ map: makeMoonTexture(), color: '#fff3d4', fog: false }),
  );
  moon.position.set(-7, 9.2, -20);
  scene.add(moon);
  const moonGlow = new THREE.Sprite(new THREE.SpriteMaterial({
    map: makeRadialTexture('rgba(255,240,205,1)', 'rgba(255,210,140,0)', 256),
    color: '#ffe8b8', transparent: true, opacity: 0.75, blending: THREE.AdditiveBlending, depthWrite: false, fog: false,
  }));
  moonGlow.position.copy(moon.position);
  moonGlow.scale.setScalar(13);
  scene.add(moonGlow);

  // horizon glow
  const haze = new THREE.Sprite(new THREE.SpriteMaterial({
    map: makeRadialTexture('rgba(160,110,210,1)', 'rgba(80,40,120,0)', 256),
    color: '#a06bd8', transparent: true, opacity: 0.32, blending: THREE.AdditiveBlending, depthWrite: false, fog: false,
  }));
  haze.position.set(0, 3.5, -30);
  haze.scale.set(48, 22, 1);
  scene.add(haze);

  // ----- ground -----
  const ground = new THREE.Mesh(
    new THREE.CircleGeometry(38, 64),
    new THREE.MeshStandardMaterial({ color: '#241834', roughness: 1, metalness: 0 }),
  );
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  scene.add(ground);

  const moss = new THREE.Mesh(
    new THREE.CircleGeometry(6.4, 48),
    new THREE.MeshStandardMaterial({ color: '#2a3c3c', roughness: 1 }),
  );
  moss.rotation.x = -Math.PI / 2;
  moss.position.y = 0.005;
  moss.receiveShadow = true;
  scene.add(moss);

  // stepping stones
  const stoneMat = new THREE.MeshStandardMaterial({ color: '#4a3d5c', roughness: 0.9 });
  for (let i = 0; i < 5; i++) {
    const s = new THREE.Mesh(new THREE.CylinderGeometry(0.36, 0.42, 0.1, 9), stoneMat);
    s.position.set(-2.3 - i * 0.55, 0.05, 2.4 + i * 0.65);
    s.rotation.y = i * 0.7;
    s.receiveShadow = true;
    scene.add(s);
  }

  // ----- pedestal -----
  const pedestal = new THREE.Group();
  const stone = new THREE.Mesh(
    new THREE.CylinderGeometry(1.28, 1.42, 0.52, 32),
    new THREE.MeshStandardMaterial({ color: '#433455', roughness: 0.92 }),
  );
  stone.position.y = 0.26;
  stone.castShadow = true;
  stone.receiveShadow = true;
  pedestal.add(stone);

  const woodTop = new THREE.Mesh(
    new THREE.CylinderGeometry(1.16, 1.2, 0.14, 32),
    new THREE.MeshStandardMaterial({ color: '#6d4b34', roughness: 0.8 }),
  );
  woodTop.position.y = 0.58;
  woodTop.castShadow = true;
  woodTop.receiveShadow = true;
  pedestal.add(woodTop);

  const mossTop = new THREE.Mesh(
    new THREE.CylinderGeometry(1.13, 1.13, 0.035, 32),
    new THREE.MeshStandardMaterial({ color: '#3e5b4a', roughness: 0.95 }),
  );
  mossTop.position.y = 0.665;
  mossTop.receiveShadow = true;
  pedestal.add(mossTop);

  // rune ring on the stone
  const runeMat = new THREE.MeshBasicMaterial({ color: '#a98aff', transparent: true, opacity: 0.35 });
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * Math.PI * 2;
    const rune = new THREE.Mesh(new THREE.BoxGeometry(0.055, 0.16, 0.02), runeMat);
    rune.position.set(Math.cos(a) * 1.36, 0.27, Math.sin(a) * 1.36);
    rune.rotation.y = -a + Math.PI / 2;
    pedestal.add(rune);
  }
  scene.add(pedestal);

  // ----- scenery -----
  const treeSpots = [
    [-9, -6, 1.2], [7.5, -8, 1.4], [-13, -10, 1.6], [13, -12, 1.5],
    [-17, -4, 1.8], [17, -3, 1.7], [-20, 4, 2], [20, 6, 1.9],
    [-11, -15, 1.3], [11, -16, 1.4],
  ];
  for (const [x, z, s] of treeSpots) {
    const t = buildTree(s);
    t.position.set(x, 0, z);
    t.rotation.y = Math.random() * Math.PI;
    scene.add(t);
  }

  const fence = buildFence();
  scene.add(fence);

  buildStringLights(scene);

  // hay bales
  const hayMat = new THREE.MeshStandardMaterial({ color: '#a97833', roughness: 0.95 });
  const bandMat = new THREE.MeshStandardMaterial({ color: '#6d4a22', roughness: 0.9 });
  for (const [x, z, ry, s] of [[-3.3, -1.6, 0.4, 0.8], [3.4, -2.2, -0.3, 0.65], [4.6, 0.4, 1.1, 0.55]]) {
    const hay = new THREE.Group();
    const roll = new THREE.Mesh(new THREE.CylinderGeometry(0.62, 0.62, 1.15, 20), hayMat);
    roll.rotation.z = Math.PI / 2;
    roll.castShadow = true;
    roll.receiveShadow = true;
    hay.add(roll);
    for (const off of [-0.3, 0.3]) {
      const band = new THREE.Mesh(new THREE.TorusGeometry(0.63, 0.035, 6, 24), bandMat);
      band.rotation.y = Math.PI / 2;
      band.position.x = off;
      hay.add(band);
    }
    hay.position.set(x, 0.62 * s, z);
    hay.rotation.y = ry;
    hay.scale.setScalar(s);
    scene.add(hay);
  }

  // mini pumpkins
  const miniColors = ['#ff9248', '#ffb27a', '#d9c07a', '#b78cd6', '#ff8fae'];
  for (let i = 0; i < 12; i++) {
    const a = Math.random() * Math.PI * 2;
    const r = 2.2 + Math.random() * 5.5;
    const size = 0.16 + Math.random() * 0.16;
    const p = buildMiniPumpkin(miniColors[i % miniColors.length], size);
    p.position.set(Math.cos(a) * r, size * 0.62, Math.sin(a) * r * 0.8 + 0.6);
    p.rotation.y = Math.random() * Math.PI;
    scene.add(p);
  }

  // glowing mushrooms
  const mushroomSpots = [[-2.1, 1.1, 0.5], [2.0, 1.35, 0.4], [-1.5, -2.0, 0.35], [1.7, -2.3, 0.3]];
  for (const [x, z, s] of mushroomSpots) {
    const m = new THREE.Group();
    const stem = new THREE.Mesh(
      new THREE.CylinderGeometry(0.05, 0.07, 0.32, 8),
      new THREE.MeshStandardMaterial({ color: '#d8d0e8', roughness: 0.7 }),
    );
    stem.position.y = 0.16;
    const cap = new THREE.Mesh(
      new THREE.SphereGeometry(0.16, 14, 10, 0, Math.PI * 2, 0, Math.PI / 2),
      new THREE.MeshStandardMaterial({ color: '#8ff0e0', emissive: '#4ad9c9', emissiveIntensity: 0.8, roughness: 0.4 }),
    );
    cap.position.y = 0.32;
    cap.scale.y = 0.8;
    const glow = new THREE.PointLight('#7ff0df', 1.2, 2.2, 2);
    glow.position.y = 0.35;
    m.add(stem, cap, glow);
    m.position.set(x, 0, z);
    m.scale.setScalar(s * 2.2);
    scene.add(m);
  }

  // grass tufts
  const grassGeo = new THREE.ConeGeometry(0.03, 0.3, 4);
  const grassMat = new THREE.MeshStandardMaterial({ color: '#2f4a44', roughness: 1 });
  const grass = new THREE.InstancedMesh(grassGeo, grassMat, 90);
  const dummy = new THREE.Object3D();
  for (let i = 0; i < 90; i++) {
    const a = Math.random() * Math.PI * 2;
    const r = 2.5 + Math.random() * 8;
    dummy.position.set(Math.cos(a) * r, 0.14, Math.sin(a) * r * 0.8 + 0.8);
    dummy.rotation.set((Math.random() - 0.5) * 0.4, Math.random() * Math.PI, (Math.random() - 0.5) * 0.4);
    dummy.scale.setScalar(0.7 + Math.random() * 0.9);
    dummy.updateMatrix();
    grass.setMatrixAt(i, dummy.matrix);
  }
  scene.add(grass);

  // ----- fireflies -----
  const fireflyCount = 90;
  const ffPos = new Float32Array(fireflyCount * 3);
  const ffSeed = new Float32Array(fireflyCount);
  for (let i = 0; i < fireflyCount; i++) {
    ffPos[i * 3] = (Math.random() - 0.5) * 13;
    ffPos[i * 3 + 1] = 0.5 + Math.random() * 3.6;
    ffPos[i * 3 + 2] = (Math.random() - 0.5) * 8 - 0.5;
    ffSeed[i] = Math.random() * 100;
  }
  const ffGeo = new THREE.BufferGeometry();
  ffGeo.setAttribute('position', new THREE.BufferAttribute(ffPos, 3));
  ffGeo.setAttribute('aSeed', new THREE.BufferAttribute(ffSeed, 1));
  const ffMat = new THREE.ShaderMaterial({
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    uniforms: {
      uTime: { value: 0 },
      uTex: { value: makeRadialTexture('rgba(255,238,160,1)', 'rgba(255,200,80,0)', 64) },
    },
    vertexShader: `
      attribute float aSeed;
      uniform float uTime;
      varying float vAlpha;
      void main() {
        vec3 p = position;
        p.x += sin(uTime * 0.6 + aSeed) * 0.5;
        p.y += sin(uTime * 0.9 + aSeed * 1.7) * 0.28;
        p.z += cos(uTime * 0.5 + aSeed * 0.8) * 0.5;
        vec4 mv = modelViewMatrix * vec4(p, 1.0);
        vAlpha = 0.35 + 0.65 * (0.5 + 0.5 * sin(uTime * 2.0 + aSeed * 3.0));
        gl_PointSize = 12.0 * (14.0 / -mv.z);
        gl_Position = projectionMatrix * mv;
      }
    `,
    fragmentShader: `
      uniform sampler2D uTex;
      varying float vAlpha;
      void main() {
        vec4 t = texture2D(uTex, gl_PointCoord);
        gl_FragColor = vec4(t.rgb, t.a * vAlpha);
      }
    `,
  });
  const fireflies = new THREE.Points(ffGeo, ffMat);
  scene.add(fireflies);

  // ----- lights -----
  const hemi = new THREE.HemisphereLight('#a58bff', '#2a1838', 0.65);
  scene.add(hemi);

  const moonLight = new THREE.DirectionalLight('#cfe0ff', 2.2);
  moonLight.position.set(-5, 8, 4);
  moonLight.castShadow = true;
  moonLight.shadow.mapSize.set(2048, 2048);
  moonLight.shadow.camera.left = -4.5;
  moonLight.shadow.camera.right = 4.5;
  moonLight.shadow.camera.top = 4.5;
  moonLight.shadow.camera.bottom = -4.5;
  moonLight.shadow.camera.near = 0.5;
  moonLight.shadow.camera.far = 22;
  moonLight.shadow.bias = -0.0008;
  moonLight.shadow.normalBias = 0.02;
  scene.add(moonLight);

  const rim = new THREE.PointLight('#ff86c0', 26, 12, 2);
  rim.position.set(3.4, 2.2, 2.6);
  scene.add(rim);

  const fill = new THREE.DirectionalLight('#ffd9b0', 0.7);
  fill.position.set(2.5, 3.5, 6);
  scene.add(fill);

  const underGlow = new THREE.PointLight('#a87cff', 8, 6, 2);
  underGlow.position.set(0, 0.8, 1.6);
  scene.add(underGlow);

  return {
    update(dt, t) {
      starMat.uniforms.uTime.value = t;
      ffMat.uniforms.uTime.value = t;
      moonGlow.material.opacity = 0.68 + Math.sin(t * 0.7) * 0.05;
    },
  };
}

import * as THREE from 'three';

function makeGlowTexture() {
  const c = document.createElement('canvas');
  c.width = c.height = 128;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
  g.addColorStop(0, 'rgba(220,245,255,0.85)');
  g.addColorStop(0.4, 'rgba(170,210,255,0.28)');
  g.addColorStop(1, 'rgba(120,160,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 128, 128);
  return new THREE.CanvasTexture(c);
}

export class Ghost {
  constructor(scene) {
    this.group = new THREE.Group();
    this.base = new THREE.Vector3(1.42, 2.02, 0.55);
    this.group.position.copy(this.base);
    this.cheer = 0;
    this.mood = 0;
    this.moodTimer = 0;

    const bodyMat = new THREE.MeshStandardMaterial({
      color: '#e8f4ff',
      emissive: '#9dc8ff',
      emissiveIntensity: 0.34,
      roughness: 0.55,
      metalness: 0,
      transparent: true,
      opacity: 0.96,
    });

    const profile = [
      [0.001, 0.54], [0.14, 0.52], [0.27, 0.42], [0.35, 0.24],
      [0.38, 0.02], [0.36, -0.18], [0.31, -0.36], [0.29, -0.44],
    ].map(([x, y]) => new THREE.Vector2(x, y));
    const body = new THREE.Mesh(new THREE.LatheGeometry(profile, 36), bodyMat);
    body.castShadow = false;
    this.group.add(body);

    const lobeGeo = new THREE.SphereGeometry(0.085, 12, 10);
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * Math.PI * 2;
      const lobe = new THREE.Mesh(lobeGeo, bodyMat);
      lobe.position.set(Math.cos(a) * 0.255, -0.42, Math.sin(a) * 0.255);
      lobe.scale.set(1.15, 0.9, 1.15);
      this.group.add(lobe);
    }

    const eyeMat = new THREE.MeshStandardMaterial({ color: '#2b1b3e', roughness: 0.35 });
    const eyeGeo = new THREE.SphereGeometry(1, 16, 12);
    for (const side of [-1, 1]) {
      const eye = new THREE.Mesh(eyeGeo, eyeMat);
      eye.scale.set(0.052, 0.078, 0.03);
      eye.position.set(side * 0.115, 0.13, 0.32);
      this.group.add(eye);

      const shine = new THREE.Mesh(eyeGeo, new THREE.MeshBasicMaterial({ color: '#ffffff' }));
      shine.scale.set(0.016, 0.022, 0.01);
      shine.position.set(side * 0.115 - 0.016, 0.152, 0.348);
      this.group.add(shine);

      const blush = new THREE.Mesh(
        new THREE.SphereGeometry(1, 12, 10),
        new THREE.MeshBasicMaterial({ color: '#ffa9c9', transparent: true, opacity: 0.8 }),
      );
      blush.scale.set(0.05, 0.03, 0.012);
      blush.position.set(side * 0.215, 0.045, 0.305);
      this.group.add(blush);
    }

    const mouth = new THREE.Mesh(
      new THREE.TorusGeometry(0.032, 0.011, 6, 14, Math.PI),
      eyeMat,
    );
    mouth.position.set(0, 0.03, 0.352);
    mouth.rotation.z = Math.PI;
    this.group.add(mouth);

    const armGeo = new THREE.SphereGeometry(0.075, 12, 10);
    for (const side of [-1, 1]) {
      const arm = new THREE.Mesh(armGeo, bodyMat);
      arm.scale.set(0.9, 1.5, 0.7);
      arm.position.set(side * 0.39, 0.0, 0.02);
      this.group.add(arm);
    }

    const glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: makeGlowTexture(),
      color: '#bfe0ff',
      transparent: true,
      opacity: 0.65,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    }));
    glow.scale.setScalar(2.3);
    glow.position.z = -0.4;
    this.group.add(glow);
    this.glow = glow;

    this.group.scale.setScalar(0.95);
    scene.add(this.group);
  }

  react(kind) {
    this.mood = kind === 'happy' ? 1 : -1;
    this.moodTimer = 1.8;
    if (kind === 'happy') this.cheer = 1;
  }

  update(dt, t) {
    this.cheer = Math.max(0, this.cheer - dt * 1.6);
    this.moodTimer = Math.max(0, this.moodTimer - dt);
    if (this.moodTimer === 0) this.mood = 0;

    const bob = Math.sin(t * 1.35) * 0.055;
    const hop = Math.sin((1 - this.cheer) * Math.PI) * 0;
    const jump = this.cheer > 0 ? Math.sin(this.cheer * Math.PI * 1.2) * 0.22 : 0;
    this.group.position.set(
      this.base.x + Math.sin(t * 0.6) * 0.035,
      this.base.y + bob + jump + hop,
      this.base.z,
    );
    const tilt = Math.sin(t * 0.9) * 0.035;
    this.group.rotation.z = tilt + this.mood * 0.1 * Math.sin(this.moodTimer * 8) * 0.4;
    this.group.rotation.y = Math.sin(t * 0.5) * 0.08;

    const pulse = 1 + this.cheer * 0.08;
    this.group.scale.setScalar(0.95 * pulse);
    this.glow.material.opacity = 0.55 + Math.sin(t * 2.2) * 0.1 + this.cheer * 0.25;
  }
}

// Tiny synthesized sound kit — no audio files, all WebAudio.
export class Sfx {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
  }

  init() {
    if (!this.ctx) {
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if (!Ctx) return;
      this.ctx = new Ctx();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0.42;
      this.master.connect(this.ctx.destination);
    }
    if (this.ctx.state === 'suspended') this.ctx.resume();
  }

  setMuted(m) {
    this.muted = m;
    if (this.master) this.master.gain.value = m ? 0 : 0.42;
  }

  _tone(freq, dur, { type = 'sine', vol = 0.2, at = 0, slideTo = null, attack = 0.008 } = {}) {
    if (!this.ctx || this.muted) return;
    const t0 = this.ctx.currentTime + at;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (slideTo) osc.frequency.exponentialRampToValueAtTime(Math.max(1, slideTo), t0 + dur);
    gain.gain.setValueAtTime(0.0001, t0);
    gain.gain.exponentialRampToValueAtTime(vol, t0 + attack);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(gain).connect(this.master);
    osc.start(t0);
    osc.stop(t0 + dur + 0.05);
  }

  _noise(dur, { vol = 0.08, at = 0, freq = 900, q = 0.8 } = {}) {
    if (!this.ctx || this.muted) return;
    const t0 = this.ctx.currentTime + at;
    const len = Math.max(1, Math.floor(this.ctx.sampleRate * dur));
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / len);
    const src = this.ctx.createBufferSource();
    src.buffer = buf;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = freq;
    filter.Q.value = q;
    const gain = this.ctx.createGain();
    gain.gain.value = vol;
    src.connect(filter).connect(gain).connect(this.master);
    src.start(t0);
  }

  click() {
    this.init();
    this._tone(760, 0.07, { type: 'triangle', vol: 0.09 });
  }

  plop() {
    this.init();
    this._tone(620, 0.13, { type: 'sine', vol: 0.18, slideTo: 260 });
    this._noise(0.07, { vol: 0.04, freq: 1800 });
  }

  chime() {
    this.init();
    this._tone(880, 0.22, { type: 'sine', vol: 0.1 });
    this._tone(1320, 0.26, { type: 'sine', vol: 0.06, at: 0.04 });
  }

  success() {
    this.init();
    const notes = [523.25, 659.25, 783.99, 1046.5];
    notes.forEach((n, i) => {
      this._tone(n, 0.3, { type: 'triangle', vol: 0.11, at: i * 0.075 });
      this._tone(n * 2, 0.18, { type: 'sine', vol: 0.035, at: i * 0.075 });
    });
  }

  perfect() {
    this.init();
    const notes = [659.25, 783.99, 1046.5, 1318.5, 1567.98];
    notes.forEach((n, i) => {
      this._tone(n, 0.42, { type: 'sine', vol: 0.1, at: i * 0.08 });
    });
    this._noise(0.5, { vol: 0.03, freq: 4000 });
  }

  fail() {
    this.init();
    this._tone(392, 0.28, { type: 'triangle', vol: 0.1, slideTo: 262 });
    this._tone(196, 0.34, { type: 'sine', vol: 0.07, at: 0.1, slideTo: 160 });
  }

  tick() {
    this.init();
    this._tone(1500, 0.035, { type: 'square', vol: 0.03 });
  }

  swoosh() {
    this.init();
    this._noise(0.4, { vol: 0.05, freq: 700, q: 0.4 });
  }
}

