  content: "✓";
  position: absolute;
  top: -6px; right: -6px;
  width: 19px; height: 19px;
  display: grid; place-items: center;
  border-radius: 50%;
  background: var(--gold);
  color: #3b1830;
  font-size: 11px;
  font-weight: 900;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
}
.opt-name { white-space: nowrap; }
.opt-icon { font-size: 21px; line-height: 1; }
.opt[data-kind="face"] { flex-direction: column; justify-content: center; gap: 1px; min-width: 78px; height: 82px; }
.opt[data-kind="face"] .opt-name { font-size: 10.5px; }
