  justify-content: center;
  gap: 2px;
  min-width: 80px;
  height: 74px;
}
.opt[data-kind="acc"] .opt-icon, .opt[data-kind="stamp"] .opt-icon { font-size: 24px; }
.opt[data-kind="stamp"] .stamp-icon { filter: drop-shadow(0 0 8px rgba(255, 220, 140, 0.45)); }

.stamp-meta {
  flex: 0 0 auto;
  align-self: center;
  margin-left: auto;
  padding: 0 10px;
  font-size: 10.5px;
  line-height: 1.4;
  color: #b7a2d3;
  max-width: 130px;
}
.stamp-meta b { color: var(--gold); font-size: 13px; }

.stamp-hint {
  height: 0;
  overflow: hidden;
  opacity: 0;
  text-align: center;
  font-size: 10.5px;
  color: #c4b0df;
  letter-spacing: 0.02em;
  transition: height 0.25s, opacity 0.25s, padding 0.25s;
}
.stamp-hint.show { height: 18px; opacity: 0.9; padding-top: 3px; }

/* ------------------------------------------------ free banner + toast */
.free-banner {
  position: absolute;
  top: 92px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 7px 8px 7px 18px;
  border-radius: 999px;
  background: rgba(32, 19, 50, 0.72);
  border: 1px solid var(--stroke);
  backdrop-filter: blur(14px);
  font-size: 12px;
  color: #e4d4f7;
  z-index: 6;
  box-shadow: var(--shadow);
}
.free-banner.hidden { display: none; }
.mini-btn {
  border: none;
  border-radius: 999px;
  padding: 7px 14px;
  font-family: inherit;
  font-size: 11px;
  font-weight: 800;
  color: #42112f;
  background: linear-gradient(135deg, #ffe6a8, #ffb2d0);
  cursor: pointer;
}

.toast {
  position: absolute;
  left: 50%;
  bottom: 208px;
  transform: translate(-50%, 12px);
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 10px 22px;
  border-radius: 999px;
  background: rgba(30, 18, 48, 0.92);
  border: 1px solid rgba(255, 220, 255, 0.22);
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.45);
  backdrop-filter: blur(12px);
  font-size: 13px;
  font-weight: 700;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  z-index: 9;
  transition: opacity 0.25s, transform 0.25s;
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }
.toast b { font-size: 17px; color: var(--gold); }
.toast.perfect {
  background: linear-gradient(120deg, rgba(255, 220, 140, 0.97), rgba(255, 160, 195, 0.97));
  border-color: rgba(255, 250, 230, 0.9);
  color: #42112f;
  box-shadow: 0 18px 50px rgba(255, 150, 180, 0.45);
}
.toast.perfect b { color: #8a2450; }
.toast.good { border-color: rgba(140, 231, 196, 0.55); }
.toast.bad { border-color: rgba(255, 125, 140, 0.55); }

.photo-hint {
  position: absolute;
  left: 50%;
  bottom: 26px;
  transform: translate(-50%, 10px);
  padding: 10px 18px;
  border-radius: 999px;
  background: rgba(20, 10, 32, 0.7);
  border: 1px solid var(--stroke);
  font-size: 12px;
  color: #e4d4f7;
  opacity: 0;
  pointer-events: none;
  z-index: 30;
  transition: opacity 0.3s, transform 0.3s;
}
.photo-hint.show { opacity: 1; transform: translate(-50%, 0); }

body.photo-mode .hud,
body.photo-mode .tray,
body.photo-mode .order-panel,
body.photo-mode .free-banner,
body.photo-mode .toast {
  opacity: 0 !important;
  pointer-events: none !important;
  transform: translateY(24px);
}
body.photo-mode .order-panel { transform: translateY(10px); }

/* ------------------------------------------------ overlays */
.overlay {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 26px;
  transition: opacity 0.4s, visibility 0.4s;
}
.overlay.hidden { opacity: 0; visibility: hidden; pointer-events: none; }

.start-overlay {
  justify-content: flex-start;
  padding-left: max(5.5vw, 30px);
  background:
    radial-gradient(ellipse at 82% 30%, rgba(255, 160, 200, 0.08), transparent 45%),
    linear-gradient(100deg, rgba(11, 6, 20, 0.95) 0%, rgba(11, 6, 20, 0.88) 32%, rgba(11, 6, 20, 0.42) 58%, rgba(11, 6, 20, 0) 80%);
}

.start-card { width: min(560px, 100%); }
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--gold);
}
.eyebrow::before {
  content: "";
  width: 22px; height: 1px;
  background: linear-gradient(90deg, transparent, var(--gold));
}
.start-card h1 {
  margin: 14px 0 16px;
  font-size: clamp(44px, 6.4vw, 76px);
  line-height: 0.9;
  letter-spacing: -0.025em;
  color: #fff8ec;
  text-shadow: 0 18px 50px rgba(255, 120, 180, 0.2);
}
.start-card h1 em {
  font-style: normal;
  background: linear-gradient(100deg, #ffd36e, #ff9ec4 52%, #c9a7ff);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.lede {
  max-width: 470px;
  margin: 0;
  font-size: 14.5px;
  line-height: 1.62;
  color: #d9c9ec;
}
.feature-row {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin: 24px 0 26px;
  max-width: 500px;
}
.feature {
  padding: 10px 12px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.055);
  border: 1px solid rgba(255, 220, 255, 0.12);
}
.feature b {
  display: block;
  font-size: 9px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #ffd7e6;
  margin-bottom: 3px;
}
.feature span { font-size: 12px; color: #f4e9ff; font-weight: 700; }

.start-actions { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.primary-btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  border: none;
  border-radius: 16px;
  padding: 14px 22px;
  font-family: inherit;
  font-size: 14.5px;
  font-weight: 900;
  color: #42112f;
  background: linear-gradient(135deg, #ffe6a8, #ffb2d0 58%, #ff8fba);
  box-shadow: 0 16px 36px rgba(255, 130, 170, 0.34), inset 0 1px 0 rgba(255, 255, 255, 0.72);
  cursor: pointer;
  transition: transform 0.15s, box-shadow 0.2s;
}
.primary-btn span { font-size: 17px; }
.primary-btn:hover { transform: translateY(-2px); box-shadow: 0 20px 42px rgba(255, 130, 170, 0.48); }
.primary-btn:active { transform: scale(0.97); }
.ghost-btn {
  border: 1px solid rgba(255, 220, 255, 0.22);
  border-radius: 16px;
  padding: 14px 20px;
  font-family: inherit;
  font-size: 13px;
  font-weight: 800;
  color: #f0e4ff;
  background: rgba(255, 255, 255, 0.055);
  cursor: pointer;
  transition: background 0.2s, transform 0.15s;
}
.ghost-btn:hover { background: rgba(255, 255, 255, 0.1); transform: translateY(-1px); }

.controls-hint {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 16px;
  margin-top: 20px;
  font-size: 10.5px;
  color: #a995c7;
}
.controls-hint span { white-space: nowrap; }

.results-overlay {
  background: radial-gradient(circle at 50% 38%, rgba(70, 36, 104, 0.55), rgba(8, 4, 16, 0.88) 70%);
  backdrop-filter: blur(5px);
}
.results-card {
  width: min(520px, 100%);
  padding: 30px 30px 26px;
  border-radius: 28px;
  background: linear-gradient(180deg, rgba(52, 31, 78, 0.92), rgba(26, 15, 42, 0.95));
  border: 1px solid rgba(255, 220, 255, 0.18);
  box-shadow: var(--shadow);
  text-align: center;
  backdrop-filter: blur(18px);
}
.rank {
  width: 92px; height: 92px;
  margin: 0 auto 16px;
  display: grid; place-items: center;
  border-radius: 50%;
  font-size: 46px;
  font-weight: 900;
  color: #42112f;
  background: linear-gradient(145deg, #ffe9a8, #ffb3cf);
  border: 3px solid rgba(255, 255, 255, 0.55);
  box-shadow: 0 0 40px rgba(255, 180, 150, 0.45), inset 0 2px 8px rgba(255, 255, 255, 0.5);
}
.rank[data-rank="S"] { background: linear-gradient(145deg, #fff3b0, #ffd36e 45%, #ff9ec4); box-shadow: 0 0 55px rgba(255, 200, 110, 0.6); }
.rank[data-rank="A"] { background: linear-gradient(145deg, #d7fff0, #8ce7c4 55%, #b795ff); }
.rank[data-rank="B"] { background: linear-gradient(145deg, #e7dbff, #b795ff 55%, #8fb8ff); color: #2d1745; }
.rank[data-rank="C"] { background: linear-gradient(145deg, #e2dbea, #a49ab8); color: #2d1745; }
.results-card .eyebrow { justify-content: center; }
.results-card h2 { margin: 10px 0 6px; font-size: 30px; letter-spacing: -0.01em; }
.results-card > p { margin: 0; font-size: 13.5px; line-height: 1.55; color: #d4c2e9; }
.result-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 22px 0;
  padding: 14px 8px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.045);
  border: 1px solid rgba(255, 255, 255, 0.07);
}
.result-stats small {
  display: block;
  font-size: 8.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #bda8d9;
  margin-bottom: 3px;
}
.result-stats b { font-size: 22px; font-variant-numeric: tabular-nums; }
.results-card .start-actions { justify-content: center; }

/* ------------------------------------------------ responsive */
@media (max-width: 900px) {
  .hud { padding: max(12px, env(safe-area-inset-top)) 14px 0; }
  .brand-mark { width: 38px; height: 38px; font-size: 20px; border-radius: 13px; }
  .brand-text b { font-size: 14px; }
  .brand-text span { font-size: 8px; }
  .score-chip, .combo-chip { min-width: 64px; padding: 5px 9px 6px; border-radius: 12px; }
  .score-chip small, .combo-chip small { font-size: 7px; }
  .score-chip b, .combo-chip b { font-size: 15px; }
  .icon-btn { width: 36px; height: 36px; border-radius: 11px; font-size: 14px; }

  .order-panel {
    top: 66px;
    left: 10px;
    right: 10px;
    width: auto;
    padding: 11px 12px 11px;
    border-radius: 20px;
  }
  .spirit-badge { width: 36px; height: 36px; font-size: 18px; }
  .order-title b { font-size: 13.5px; }
  .order-title span { font-size: 10.5px; }
  .wish-list {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 5px;
    padding: 8px 0 4px;
  }
  .wish-list li { margin: 0; padding: 5px 7px; font-size: 11px; gap: 6px; border-radius: 10px; }
  .req-mark { width: 16px; }
  .req-emoji { font-size: 12px; }
  .req-count { font-size: 9px; padding: 1px 5px; }
  .timebar { margin-top: 5px; height: 6px; }
  .order-foot { margin-top: 6px; }
  #timeText { font-size: 14px; }
  .serve-btn { padding: 8px 14px; font-size: 12px; border-radius: 12px; }

  .tray {
    bottom: max(8px, env(safe-area-inset-bottom));
    width: calc(100% - 16px);
    padding: 9px 10px 8px;
    border-radius: 22px;
  }
  .tray-head { flex-wrap: wrap; gap: 6px; }
  .tabs { flex: 1 1 100%; justify-content: space-between; padding: 3px; }
  .tab { padding: 6px 8px; font-size: 11px; flex: 1; text-align: center; }
  .tray-tools { width: 100%; justify-content: flex-end; gap: 5px; }
  .tool-btn { padding: 5px 8px; font-size: 10px; }
  .options { padding: 7px 0 0; gap: 6px; }
  .opt { height: 50px; min-width: 80px; padding: 6px 9px; font-size: 10.5px; border-radius: 14px; }
  .opt[data-kind="face"] { height: 70px; min-width: 70px; }
  .opt .face-preview { width: 40px !important; height: 40px !important; }
  .opt[data-kind="acc"], .opt[data-kind="stamp"] { height: 64px; min-width: 70px; }
  .opt[data-kind="acc"] .opt-icon, .opt[data-kind="stamp"] .opt-icon { font-size: 21px; }
  .stamp-meta { display: none; }
  .stamp-hint.show { height: 16px; font-size: 9.5px; }

  .free-banner { top: 66px; font-size: 11px; padding: 6px 7px 6px 14px; }
  .toast { bottom: 196px; font-size: 12px; padding: 9px 18px; }
  .photo-hint { bottom: 16px; }

  .start-overlay {
    justify-content: center;
    padding: 20px;
    background: radial-gradient(circle at 50% 30%, rgba(70, 36, 104, 0.4), rgba(9, 5, 18, 0.9) 62%);
  }
  .start-card { width: min(520px, 100%); }
  .start-card h1 { font-size: clamp(40px, 11vw, 58px); }
  .lede { font-size: 13px; }
  .feature-row { margin: 18px 0 20px; }
  .feature { padding: 8px 9px; }
  .feature span { font-size: 11px; }
  .controls-hint { display: none; }
  .results-card { padding: 24px 18px 20px; border-radius: 24px; }
  .results-card h2 { font-size: 25px; }
}

@media (max-width: 640px) {
  .brand-text span { display: none; }
  .scorebar { gap: 5px; }
  .score-chip, .combo-chip { min-width: 56px; }
  .brand-text b { font-size: 12.5px; }
  .brand-mark { width: 34px; height: 34px; font-size: 18px; }
  .icon-btn { width: 32px; height: 32px; font-size: 13px; }
  .order-panel { top: 60px; }
  .start-card h1 { font-size: 42px; }
  .feature-row { gap: 5px; }
  .feature b { font-size: 8px; }
  .feature span { font-size: 10px; }
  .start-actions { width: 100%; }
  .primary-btn { flex: 1; justify-content: center; }
  .ghost-btn { flex: 0 0 auto; }
  .result-stats b { font-size: 19px; }
  .results-card h2 { font-size: 22px; }
  .toast { white-space: normal; max-width: calc(100% - 28px); text-align: center; bottom: 190px; }
}

@media (max-height: 740px) and (min-width: 901px) {
  .order-panel { top: 76px; padding: 12px 14px; }
  .wish-list { padding: 9px 0 4px; }
  .wish-list li { padding: 5px 8px; margin-bottom: 4px; font-size: 12px; }
  .tray { padding: 8px 12px 7px; }
  .options { padding-top: 7px; }
  .opt { height: 50px; }
  .opt[data-kind="face"] { height: 72px; }
  .opt[data-kind="acc"], .opt[data-kind="stamp"] { height: 64px; }
  .toast { bottom: 180px; }
  .start-card h1 { font-size: 58px; margin: 10px 0 12px; }
  .lede { font-size: 13px; }
  .feature-row { margin: 16px 0 18px; }
}

